		const getUserInfo = vi.fn(() => Effect.succeed({ data: undefined }));
		const operation = createUserGetOperation({ getUserInfo });

		await expect(
			Effect.runPromise(operation.effect()),
		).resolves.toBeUndefined();
		expect(getUserInfo).toHaveBeenCalledWith();
	});
});


